def identity_consistency(anchor_png: Path, video: Path) -> dict:
    """Same-person check against the approved keyframe (frames without a visible face are skipped)."""
    try:
        res = face_identity.verify_shot_identity(anchor_png, video, n_frames=10, threshold=CHAIN_IDENTITY_THRESHOLD)
    except ValueError as exc:  # no face in the anchor (e.g. a product-only keyframe)
        return {"skipped": str(exc), "passed": True}
    if not res["face_found"]:
        res["passed"] = True  # back view / product insert: nothing to compare, not a failure
        res["note"] = "no face in sampled frames"
    return res

