def face_similarity_threshold() -> float:
    raw = os.environ.get("KOL_FACE_SIMILARITY_THRESHOLD", "").strip()
    if raw:
        try:
            return float(raw)
        except ValueError:
            pass
    return DEFAULT_FACE_SIMILARITY_THRESHOLD
